//###########################################################
/** Chat message functions */
/* currently implemented chat functions
- Active Mods
- Rule of One
- Information on used Karma
- Information on used Devotions
- Final Step
- Extra Successes
- Success or failure of roll
- "Roll Damage/Effect" - Button
- Apply Effect - Button
*/
/* chat message functions to be implemented
- Counter Physical Attack - Button leading to a Popup with potential choices
- Counter Spell Attack - Button leading to a Popup with potential choices (are there more than Iron Will?)
- Counter Social Attack - Button leading to a Popup with potential choices (are there more than Resist Taunt?)
- enhance "Roll Damage/Effect" Popup by including Damage adder of Charakter, like Thunderslam
*/
//###########################################################

const ActionType = Object.freeze({
  TARGETTING: 'targetting',
  NONTARGETTING: 'nontargetting',
  EFFECT: 'effect',
});

export function getChatSuccess(content, user, userId) {
  let speaker = ChatMessage.getSpeaker({ alias: user.name });
  ChatMessage.create({
    content: content,
    whisper: userId,
    speaker: speaker,
  });
}

export async function chatOutput(input, roll) {
  // console.log('[EARTHDAWN] Chat Input', input);

  let rollMode = game.settings.get('core', 'rollMode');

  //###########################################################
  /** message types  */
  //###########################################################
  let rollAction;
  let targetActionType = ActionType.TARGETTING;
  if (
    input.weaponId !== null &&
    input.rolltype !== 'weapondamage' &&
    input.rolltype !== 'unarmeddamage' &&
    input.rolltype !== 'recovery' &&
    input.rolltype !== 'recoveryAbility' &&
    input.rolltype !== 'weapondamageRanged' &&
    input.rolltype !== 'attackdamage' &&
    input.rolltype !== 'testdamage' &&
    input.rolltype !== 'spelldamage' &&
    input.rolltype !== 'spellEffect' &&
    input.type !== 'power'
  ) {
    rollAction = input.talent + ` (` + input.weaponName + `)`;
  } else if (input.talent === 'Damage') {
    rollAction = `${game.i18n.localize('earthdawn.d.damage')}` + ` (` + input.weaponName + `)`;
  } else if (input.rolltype === 'spell') {
    rollAction = input.talent + ` (` + input.spellName + `)`;
  } else if (input.rolltype === 'arbitraryDice') {
    rollAction = `${game.i18n.localize('earthdawn.a.arbitraryRolls')}!`;
  } else {
    rollAction = input.talent;
    targetActionType = checkIfRollIsTargetting(input);
  }

  //input.type !== 'power'
  if (input.rolltype !== 'arbitraryDice') {
    const title = `${input.name} ${game.i18n.localize('earthdawn.r.rolls')} ${rollAction}!`;
    const blind = rollMode === 'blindroll';
    const whisper = ['gmroll', 'blindroll'].includes(rollMode) ? ChatMessage.getWhisperRecipients('GM') : [];
    const speaker = ChatMessage.getSpeaker({ alias: name });

    //###########################################################
    /** Flavor constructor  */
    //###########################################################
    const flavor = title + getKarma(input) + getDevotion(input) + getRoll(input) + (await getActiveMods(input));
    var content = await roll.render();
    var contentGM = '';

    if (targetActionType == ActionType.NONTARGETTING) {
      content += `<span class="flavor-text" style="font-size: 1.2em">`;
      content += getRuleOfOne(input, roll);
      contentGM = getSuccessFailure(input, roll);
      if (input.margin >= 0) {
        contentGM += getExtraSucess(input);
        contentGM += getEffects(input);
      }
    } else {
      var targets = Array.from(game.user.targets);
      for (let i = 0; i < targets.length; ++i) {
        const { img, name } = targets[i].actor;
        const id = targets[i].id;
        content += `<span class="flavor-text" style="font-size: 1.2em">`;
        if (i == 0) {
          content += getRuleOfOne(input, roll);
          contentGM = getSuccessFailure(input, roll);
        }
        if (i == 0) {
          if (input.margin >= 0) {
            contentGM += getExtraSucess(input);
          }
          if (!(input.margin < 0)) {
            content += getAttack(input);
          }
          let actor = game.actors.get(input.actorId);
          if (actor) {
            content += getSingleEffect(input, actor.img, actor.name);
          } else {
            content += getSingleEffect(input, img, name);
          }
        }
        if (targetActionType == ActionType.TARGETTING) {
          content += getDamage(input, id, img, name);
        }
        if (input.margin >= 0) {
          content += getHitTarget(input, img, name, targetActionType);
          content += getEffects(input, id);
        }

        content += `</span>`;
        if (checkIfWeaving(input)) {
          break;
        }
      }
    }

    await roll.toMessage({ flavor, blind, whisper, speaker, content });
    if (contentGM) {
      if (game.settings.get('earthdawn4e', 'successFailureOnlyForGM')) {
        await socketlib.system.executeAsGM('showSuccessFailure', contentGM, game.users.current, game.users.activeGM.id);
      } else {
        //await socketlib.system.executeForEveryone('showSuccessFailure', contentGM, game.users.current, game.users.activeGM.id);
        getChatSuccess(contentGM, game.users.current);
        // getChatSuccess(contentGM, game.users.current, game.users.current.id);
      }
    }
  } else if (input.rolltype === 'arbitraryDice') {
    const title = `${game.i18n.localize('earthdawn.a.arbitraryRolls')}!`;
    const blind = rollMode === 'blindroll';
    const whisper = ['gmroll', 'blindroll'].includes(rollMode) ? ChatMessage.getWhisperRecipients('GM') : [];
    const speaker = ChatMessage.getSpeaker({ alias: name });
    //###########################################################
    /** Flavor constructor  */
    //###########################################################
    const flavor = title + getKarma(input) + getDevotion(input) + getRoll(input) + getRuleOfOne(input, roll);
    await roll.toMessage({ flavor, blind, whisper, speaker });
  }
}

//###########################################################
/** Roll Action Type */
//###########################################################
function checkIfRollIsTargetting(input) {
  if (
    input.rolltype === 'weapondamage' ||
    input.rolltype === 'attackdamage' ||
    input.rolltype === 'weapondamageRanged' ||
    input.rolltype === 'spelldamage' ||
    input.rolltype === 'unarmeddamage'
  ) {
    return ActionType.TARGETTING;
  }

  if (input.talentID != null) {
    let actor = game.actors.get(input.actorId);
    let talent = actor.items.get(input.talentID._id);
    const targets = Array.from(game.user.targets);

    if (talent != undefined && talent.hasOwnProperty('effects') && talent.effects.size > 0 && targets.length > 0) {
      return ActionType.EFFECT;
    }
  }

  return ActionType.NONTARGETTING;
}

//###########################################################
/** One Weave Thread mesage regardless of target number */
//###########################################################
function checkIfWeaving(input) {
  return input.talent.includes('Thread Weaving');
}

//###########################################################
/** Active Mods */
/*  active Mods will be all modifiers affecting rolls.*/
//###########################################################
async function getActiveMods(input) {
  const template = 'systems/earthdawn4e/templates/chat/activeMods.hbs';
  const templateData = {};
  templateData['messageData'] = input;
  return await renderTemplate(template, templateData);
}

//###########################################################
/** Rule of One */
/*  Calculation part: if two or more dice show a one --> Failure */
//###########################################################

function calculateRuleOfOne(input, roll) {
  let Ones = 0;
  let notOnes = 0;
  roll.dice.forEach((set) => {
    set.results.forEach((dieResult) => {
      if (dieResult.result === 1) Ones++;
    });
  });
  roll.dice.forEach((set) => {
    set.results.forEach((dieResult) => {
      if (dieResult.result !== 1) notOnes++;
    });
  });

  if (Ones > 1 && notOnes === 0) {
    input.margin = -1;
  }
  return Ones > 1 && notOnes === 0 ? true : false;
}

//###########################################################
/** Rule of One */
/*  Add html to string part: if two or more dice show a one --> Failure */
//###########################################################
function getRuleOfOne(input, roll) {
  let onlyOnes = game.i18n.localize('earthdawn.o.onlyOnes');
  return calculateRuleOfOne(input, roll) ? `<div class="rule-of-one">${onlyOnes}</div>` : '';
}

//###########################################################
/** Used Karma  */
//###########################################################
function getKarma(input) {
  if (input.rolltype !== 'arbitraryDice') {
    return input.karmaUsed > 0
      ? `<div>
            ${game.i18n.localize('earthdawn.y.youUsed')} 
            ${input.karmaUsed} ${game.i18n.localize('earthdawn.k.karma')}
         </div>`
      : '';
  } else {
    return input.karmaUsed > 0
      ? `<div>
            ${game.i18n.localize('earthdawn.r.rollContains')} 
            ${input.karmaUsed} ${game.i18n.localize('earthdawn.k.karma')}
         </div>`
      : '';
  }
}

//###########################################################
/** Used Devotioin  */
//###########################################################
function getDevotion(input) {
  if (input.rolltype !== 'arbitraryDice') {
    return input.devotionUsed > 0
      ? `<div>
          ${game.i18n.localize('earthdawn.y.youUsed')} 
          ${input.devotionUsed} ${game.i18n.localize('earthdawn.d.devotion')}
      </div>`
      : '';
  } else {
    return input.devotionUsed > 0
      ? `<div>
          ${game.i18n.localize('earthdawn.r.rollContains')} 
          ${input.devotionUsed} ${game.i18n.localize('earthdawn.d.devotion')}
      </div>`
      : '';
  }
}

//###########################################################
/** Target Hit  */
//###########################################################
function getHitTarget(input, img, name, targetActionType) {
  let effectText = '';
  if ('attackType' in input) {
    effectText = game.i18n.localize('earthdawn.h.hit');
  } else if (input.talent === 'Unarmed Combat') {
    effectText = game.i18n.localize('earthdawn.h.hitNoWeapon');
  } else if (input.talent.includes('Spellcasting')) {
    effectText = game.i18n.localize('earthdawn.a.affected');
  }
  // For Active Effects affecting targets Image of Target is presented, otherwise return
  else if (targetActionType != ActionType.EFFECT) {
    return effectText;
  }
  return `
          <hr style="margin-top: 5px; margin-bottom: 5px"/>
          <div style="position:relative; height:auto; overflow: hidden">
            <img src="${img}" alt="${name}" style="width:40px;height:40px;float:left;margin-right:5px;margin-bottom:5px;border:none"/>
            <div style="display: inline-block; vertical-align: middle; line-height:40px">${name} ${effectText}</div>.
          </div> 
          `;
}

//###########################################################
/** Knockdown and Weaving Test  */
//###########################################################
function getSingleEffect(input, img, name) {
  let effectText = '';
  if ('margin' in input) {
    if (input.talent.includes('Knockdown Test') && input.margin < 0) {
      effectText = game.i18n.localize('earthdawn.k.knockedDown');
    } else if (input.talent.includes('Thread Weaving') && input.margin >= 0) {
      name = input.name;
      let actor = game.actors.getName(name);
      img = actor?.img;
      effectText = game.i18n.localize('earthdawn.t.threadWeaved');
    } else {
      return effectText;
    }
  } else {
    return effectText;
  }
  return `
          <hr style="margin-top: 5px; margin-bottom: 5px"/>
          <div style="height:40px">
            <img src="${img}" alt="${name}" style="width:40px;height:40px;float:left;margin-right:5px;margin-bottom:5px;border:none"/>${name} ${effectText}.
          </div>`;
}
//###########################################################
/** Final Step  */
//###########################################################
function getRoll(input) {
  return `
        <div>
            <span><a class="show-hidden"><i class="fas fa-sort"></i></a> ${game.i18n.localize('earthdawn.s.step')}: ${
    input.finalstep
  }</span>
        </div>`;
}

//###########################################################
/** Successes  */
//###########################################################
function getExtraSucess(input) {
  return input.extraSuccess
    ? `<div class="extra-success">
            ${game.i18n.localize('earthdawn.y.youGot')} 
            ${input.extraSuccess} 
            ${game.i18n.localize('earthdawn.s.successExtra')}
        </div>`
    : '';
}

//###########################################################
/** Success or Failure  */
//###########################################################
function getSuccessFailure(input, roll) {
  if (checkIfRollIsTargetting(input) == ActionType.TARGETTING) {
    return '';
  } else {
    return input.total >= input.difficulty && calculateRuleOfOne(input, roll) === false
      ? `<div class="extra-success">${game.i18n.localize('earthdawn.s.success')}!</div>`
      : `<div class="rule-of-one">${game.i18n.localize('earthdawn.f.failure')}!</div>`;
  }
}

//###########################################################
/** "Roll Damage / effect" pop up */
// to be separated like Option box
//###########################################################
function getAttack(input) {
  let attackSection = '';
  if (input.rolltype === 'attack' || input.talent === 'Unarmed Combat') {
    if (input.itemtype === 'attack') {
      attackSection = `<div>
                    <a class='damageRollNPC' data-actorId='${input.actorId}' data-damageStep='${input.damage}' data-extraSuccess='${
        input.extraSuccess
      }'>
                      <u>
                        ${game.i18n.localize('earthdawn.r.rollDamage')}
                        <i class='effectTest fas fa-dice'></i>
                      </u>                        
                    </a>
                </div>`;
    } else {
      attackSection = `<div>
                    <a class='damageRoll' data-actorId='${input.actorId}' data-weaponId='${input.weaponId}' data-damageBonus='${
        input.damageBonus
      }'data-extraSuccess='${input.extraSuccess}'>
                      <u>
                        ${game.i18n.localize('earthdawn.r.rollDamage')}
                        <i class='effectTest fas fa-dice'></i>
                      </u>                        
                    </a>
                </div>`;
    }
  } else if (input.rolltype === 'spell') {
    attackSection = `<div>
                <a class='spellEffect effectTest' data-actorId='${input.actorId}' data-spellName='${input.spellName}' data-extraSuccess='${
      input.extraSuccess
    }'>
                  <u>
                    ${game.i18n.localize('earthdawn.e.effect')}
                    <i class='effectTest fas fa-dice'></i>
                  </u>
                </a>
       </div>`;
  }

  return attackSection;
}

//###########################################################
/** apply Damage
 */
//###########################################################
function getDamage(input, id, img, name) {
  let attackSection = '';
  if (checkIfRollIsTargetting(input) == ActionType.TARGETTING) {
    attackSection = `
    <hr style="margin-top: 5px; margin-bottom: 5px"/>
    <div style="height:40px">
      <img src="${img}" alt="${name}" style="width:40px;height:40px;float:left;margin-right:5px;margin-bottom:5px;border:none"/>${name} 
      <div>
        <a class='apply-damage' data-damageSource='${input.rolltype}' data-actorId='${id}' data-damageType='${
      input.damagetype
    }' data-damageTotal='${input.total}' >
          <u>
            ${game.i18n.localize('earthdawn.a.applyDamage')}
          </u>
        </a>
      </div>    
    </div>`;
  }
  return attackSection;
}

//###########################################################
/** apply Effects
 * apply Effects function in chat-listeners.js
 */
//###########################################################
function getEffects(input, targetId) {
  let effectSection = '';
  let actorId = input.actorId;
  if (targetId === undefined) {
    targetId = actorId;
  }
  const targets = Array.from(game.user.targets);
  if (input.rolltype === 'spell') {
    //console.log(input.spellId);
    let actor = game.actors.get(input.actorId);
    let spell = actor.items.get(input.spellId);

    if (spell.hasOwnProperty('effects') && spell.effects.size > 0 && targets.length > 0) {
      effectSection += `<a class='applyEffect' data-actorId='${actorId}' data-targetId='${targetId}' data-effectId='${
        input.spellId
      }' data-extraSuccess='${input.extraSuccess}'><u>${game.i18n.localize('earthdawn.a.applyEffect')}</u></a>`;
    }
  } else if (input.rolltype != 'attack') {
    if (input.rolltype === 'recovery') {
      if (targets.length > 0) {
        effectSection += `<a class='applyEffect' data-actorId='${actorId}' data-targetId='${targetId}' data-extraSuccess='${input.extraSuccess}'></a>`;
      }
    } else if (input.type === 'talent' || input.type === 'skill' || input.type === 'devotion') {
      let actor = game.actors.get(input.actorId);
      let talent = actor.items.get(input.talentID._id);

      if (input.knackID != null) {
        talent = actor.items.get(input.knackID._id);
      }
      if (talent != null && talent.hasOwnProperty('effects') && talent.effects.size > 0 && targets.length > 0) {
        if (input.knackID != null) {
          effectSection += `<a class='applyEffect' data-actorId='${actorId}' data-targetId='${targetId}' data-effectId='${
            input.knackID._id
          }' data-extraSuccess='${input.extraSuccess}'><u>${game.i18n.localize('earthdawn.a.applyEffect')}</u></a>`;
        } else {
          effectSection += `<a class='applyEffect' data-actorId='${actorId}' data-targetId='${targetId}' data-effectId='${
            input.talentID._id
          }' data-extraSuccess='${input.extraSuccess}'><u>${game.i18n.localize('earthdawn.a.applyEffect')}</u></a>`;
        }
      }
    } else if (input.type === 'power') {
      let actor = game.actors.get(input.actorId);
      let talent = actor.items.get(input.weaponId);

      if (talent != null && talent.hasOwnProperty('effects') && talent.effects.size > 0 && targets.length > 0) {
        effectSection += `<a class='applyEffect' data-actorId='${actorId}' data-targetId='${targetId}' data-effectId='${
          input.weaponId
        }' data-extraSuccess='${input.extraSuccess}'><u>${game.i18n.localize('earthdawn.a.applyEffect')}</u></a>`;
      }
    }
  } else if (input.rolltype === 'attack') {
    let actor = game.actors.get(input.actorId);
    let talent = actor.items.get(input.weaponId);

    if (talent != null && talent.hasOwnProperty('effects') && talent.effects.size > 0 && targets.length > 0) {
      effectSection += `<a class='applyEffect' data-actorId='${actorId}' data-targetId='${targetId}' data-effectId='${
        input.weaponId
      }' data-extraSuccess='${input.extraSuccess}'><u>${game.i18n.localize('earthdawn.a.applyEffect')}</u></a>`;
    }
  }

  return effectSection;
}
